FROM employers e
JOIN (VALUES
 ('Drägerwerk AG & Co. KGaA','Werkstudent Software Development','Lübeck','Werkstudent','Software Engineering','LIVE','German ad; no CEFR stated','Part-time / mobile work possible',ARRAY['Python','Automated Testing','Hardware-in-the-loop']::TEXT[],'https://erecruitment.draeger.com/index.php?ac=jobad&id=19484&language=1',DATE '2026-08-30','Top local opportunity; tailor around Python, production debugging and test automation.'),
