 ('Dr. Hesse und Partner Ingenieure','Evergreen Werkstudent pathway — Geodesy / Geoinformatics','Hamburg','Werkstudent','Geospatial','LIVE','German page; exact CEFR not stated','Onsite / field work possible',ARRAY['3D Scanning','Data Evaluation','Monitoring']::TEXT[],'https://dhpi.com/de/karriere/werkstudenten',DATE '2026-08-30','Use as a direct speculative application; specialist employer may value niche evidence.')
) AS v(company_name,title,location,opportunity_type,role_family,status,language_requirement,work_model,technology_mentions,job_url,source_date,relevance_note)
ON e.company_name = v.company_name
ON CONFLICT (employer_id, title, job_url) DO UPDATE SET
  status = EXCLUDED.status,
  verified_at = EXCLUDED.verified_at,
  relevance_note = EXCLUDED.relevance_note;

COMMIT;
